def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find all non-zero colors
    colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    if not colors:
        return [[0]]

    # Check for isolated 2x2 blocks (must check connectivity to see if >= 2x2 area)
    solution = 0

    for color in colors:
        # Get all 2x2 blocks of this color
        blocks = []
        for r in range(rows - 1):
            for c in range(cols - 1):
                if grid[r][c] == color and grid[r+1][c] == color and \
                   grid[r][c+1] == color and grid[r+1][c+1] == color:
                    blocks.append(((r, c), (r, c+1), (r+1, c), (r+1, c+1)))

        # Check connectivity
        if len(blocks) >= 1:
            # All 2x2 blocks should form exactly a 2x2 area (not overlapping or extending)
            # If there are exactly 1 block of this color forming a 2x2, mark solution as color
            # If multiple overlapping blocks, mark solution as 0
            if len(blocks) == 1:
                solution = color
            elif len(blocks) > 1:
                solution = 0

    return [[solution if solution != 0 else 0]]
